css:
.certificate-container {
    font-family: "Inter", sans-serif;
    font-size: 20px;
}

.inner-border {
    border: 8px solid #0089FF;
    border-radius: 8px;
    text-align: center;
    padding: 6rem 4rem;
    background-color: #FFFFFF;
}

.certificate-logo {
    height: 3rem;
    margin-right: 0.5rem;
}

.certificate-name {
    font-size: 2rem;
    font-weight: 500;
    color: #192734;
    margin-bottom: 0.5rem;
}

.certificate-footer {
    margin: 4rem auto 0;
    width: 70%;
    text-align: center;
}

.certificate-footer-item {
    color: #192734;
}

.cursive-font {
    font-family: cursive;
    font-weight: 600;
}

.certificate-divider {
    margin: 0.5rem 0;
}

.certificate-expiry {
    margin-left: 2rem;
}

/* Real elements (heading, paragraphs) so the PDF's tag tree has structure. The rules below
   keep the layout the old div-and-inline-style version had. They are scoped under
   .certificate-container because Frappe's print stylesheet sets margins on `.print-format p`
   and `.print-format h1`, which a bare class selector would lose to. */
.certificate-container .certificate-brand {
    margin: 0 0 5rem;
}

.certificate-container .certificate-brand-name {
    font-weight: 900;
    font-size: 1.5rem;
}

.certificate-container .certificate-title {
    margin: 0 0 5rem;
    font-size: 2rem;
    font-weight: 900;
}

.certificate-container .certificate-statement {
    margin: 0 0 12rem;
    width: 70%;
}

.certificate-container .certificate-lead,
.certificate-container .certificate-recipient {
    display: block;
    margin-bottom: 1rem;
}

.certificate-container .certificate-recipient {
    font-weight: 900;
    font-size: 1.5rem;
}

.certificate-container .certificate-detail {
    display: block;
}

.certificate-container .certificate-detail strong,
.certificate-container .certificate-people strong {
    font-weight: 900;
}

/* Was `gray`, which is 3.95:1 on white; AA needs 4.5:1. */
.certificate-container .certificate-role {
    margin: 0 0 0.5rem;
    color: #595959;
    font-weight: 500;
}

.certificate-container .certificate-people {
    margin: 0;
}

html:
{% set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) %}
{% set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name", "image"], as_dict=True) %}
{% set logo = frappe.db.get_single_value("Website Settings", "banner_image") %}
{% set brand_name = frappe.db.get_single_value("Website Settings", "app_name") %}
{% set instructors = frappe.get_all("Course Instructor", {"parent": doc.course}, pluck="instructor", order_by="idx") %}

<meta name="pdfkit-orientation" content="Landscape">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&display=swap" rel="stylesheet">

<div class="certificate-container">
    <p class="certificate-brand">
        {% if logo %}<img src="{{ logo }}" class="certificate-logo" alt="">{% endif %}
        <span class="certificate-brand-name">{{ brand_name }}</span>
    </p>

    <h1 class="certificate-title">{{ _("Certificate of Completion") }}</h1>

    <p class="certificate-statement">
        <span class="certificate-lead">{{ _("This is to certify that") }}</span>
        <strong class="certificate-recipient">{{ member.full_name }}</strong>
        <span class="certificate-detail">
            {{ _("has successfully completed the") }}
            <strong>{{ course.title }}</strong> {{ _("course") }}
            {{ _("including all required assessments") }}
            on {{ frappe.utils.format_date(doc.issue_date, "medium") }}.
        </span>
    </p>

    {% if doc.evaluator %}
    <p class="certificate-role">{{ _("Evaluated By") }}</p>
    <p class="certificate-people"><strong>{{ doc.evaluator_name }}</strong></p>
    {% else %}
    <p class="certificate-role">{{ _("Instructor") if instructors|length == 1 else _("Instructors") }}</p>
    <p class="certificate-people">
        {% for instructor in instructors %}
            {% set instructor_name = frappe.db.get_value("User", instructor, "full_name") %}
            <strong>{{ instructor_name }}</strong>{% if not loop.last %}, {% endif %}
        {% endfor %}
    </p>
    {% endif %}
</div>
